// borg also reads a file descriptor and runs a command to obtain a passphrase; borge does
// not do either yet.
func (e *Env) passphrase() string {
	if e.prompted != nil {
		return *e.prompted
	}
	if v, ok := e.lookupBorg("PASSPHRASE"); ok {
		return v
	}
	return ""
}
